# Re-evaluate demo 1 with orthogonal flood; inspect exact changed-cell evidence.
def flood_adj(grid, color, diagonals=False):
 h,w=len(grid),len(grid[0]); seen=set(); stack=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==color: stack.append((r,c))
 dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 if diagonals: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
 while stack:
  r,c=stack.pop()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and (rr,cc) not in seen:
    seen.add((rr,cc)); stack.append((rr,cc))
 return seen
for diag in [False,True]:
 s=flood_adj(demo,8,diag); p=[row[:] for row in demo]
 for r,c in s:p[r][c]=8
 print('diag',diag,'changed',len(s),'match',p==out_demo,'diff count',sum(p[r][c]!=out_demo[r][c] for r in range(12) for c in range(18)))
 print('actual changed',[(r+1,c+1) for r in range(12) for c in range(18) if demo[r][c]==0 and out_demo[r][c]==8])

g=[[0,3,3,0,3,3,3,3,3,3,0,3,3],[3,0,3,0,3,3,3,3,3,3,3,3,3,3],[0,3,3,3,3,3,3,3,3,3,3,3,3,0],[3,3,0,3,3,3,0,3,0,0,0,0,3,3],[0,3,3,3,3,3,3,0,0,3,0,3,3,3],[0,3,3,0,0,3,3,0,3,0,0,0,3,3],[3,3,3,0,3,3,0,3,3,3,0,3,3,3],[3,3,3,3,0,3,0,3,3,3,3,0,3,0],[3,3,3,3,3,3,3,3,3,3,3,0,3,3],[3,3,3,3,3,0,3,0,3,0,0,3,3,0],[0,0,3,3,3,3,0,3,0,3,3,3,3,3],[0,8,3,8,8,8,8,3,3,3,3,0,3,0],[3,0,8,3,3,8,3,3,3,3,3,3,3,3],[3,3,3,3,0,8,3,3,3,3,0,0,0,3],[3,3,3,3,3,3,0,3,3,3,3,3,0,3],[0,0,3,0,3,0,3,3,3,3,3,3,3,3]]
# find 8-connected seed components
seeds={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
comps=[]
while seeds:
 st=[seeds.pop()]; comp=set(st)
 while st:
  r,c=st.pop()
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    p=(r+dr,c+dc)
    if (dr or dc) and p in seeds: seeds.remove(p);comp.add(p);st.append(p)
 comps.append(comp)
print('components', [[(r+1,c+1) for r,c in sorted(x)] for x in comps])
# translated placements where each component maps to zeros
placements=[]
for comp in comps:
 mr=min(r for r,c in comp); mc=min(c for r,c in comp)
 shape={(r-mr,c-mc) for r,c in comp}
 h,w=len(g),len(g[0]); hits=[]
 for ar in range(h-max(r for r,c in shape)):
  for ac in range(w-max(c for r,c in shape)):
   coords={(ar+r,ac+c) for r,c in shape}
   if all(g[r][c]==0 for r,c in coords): hits.append((ar,ac,coords))
 print('shape size/bbox',len(shape),max(r for r,c in shape)+1,max(c for r,c in shape)+1,'hits',[(r+1,c+1) for r,c,_ in hits])
 placements+=hits
res=[row[:] for row in g]
for _,_,coords in placements:
 for r,c in coords:res[r][c]=8
print('output:')
for row in res: print(row)

g=[[0,3,3,0,3,3,3,3,3,3,0,3,3],[3,0,3,0,3,3,3,3,3,3,3,3,3,3],[0,3,3,3,3,3,3,3,3,3,3,3,3,0],[3,3,0,3,3,3,0,3,0,0,0,0,3,3],[0,3,3,3,3,3,3,0,0,3,0,3,3,3],[0,3,3,0,0,3,3,0,3,0,0,0,3,3],[3,3,3,0,3,3,0,3,3,3,0,3,3,3],[3,3,3,3,0,3,0,3,3,3,3,0,3,0],[3,3,3,3,3,3,3,3,3,3,3,0,3,3],[3,3,3,3,3,0,3,0,3,0,0,3,3,0],[0,0,3,3,3,3,0,3,0,3,3,3,3,3],[0,8,3,8,8,8,8,3,3,3,3,0,3,0],[3,0,8,3,3,8,3,3,3,3,3,3,3,3],[3,3,3,3,0,8,3,3,3,3,0,0,0,3],[3,3,3,3,3,3,0,3,3,3,3,3,0,3],[0,0,3,0,3,0,3,3,3,3,3,3,3,3]]
pts={(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==8}
# create unique D4 normalized sets
transforms=set()
for refl in (False,True):
 for k in range(4):
  p=[]
  for r,c in pts:
   if refl:c=-c
   for _ in range(k):r,c=c,-r
   p.append((r,c))
  mr=min(r for r,c in p);mc=min(c for r,c in p)
  transforms.add(frozenset((r-mr,c-mc) for r,c in p))
add=set(); placements=[]; h,w=len(g),len(g[0])
for shape in transforms:
 for ar in range(h-max(r for r,c in shape)):
  for ac in range(w-max(c for r,c in shape)):
   cells={(ar+r,ac+c) for r,c in shape}
   if all(g[r][c]==0 for r,c in cells):
    placements.append((ar,ac,shape));add |= cells
print('orientation count',len(transforms),'placement count',len(placements),'changed union',len(add))
for r in range(h):
 print(' '.join(str(8 if (r,c) in add else g[r][c]) for c in range(w)))
